func rolloutPhaseLabel(phase string) string {
	switch phase {
	case "preparing":
		return "Checking nodes"
	case "updating":
		return "Updating cluster"
	case "verifying":
		return "Verifying cluster"
	case "queued":
		return "Waiting"
	case "install":
		return "Installing"
	case "restart", "restarting":
		return "Restarting"
	case "complete":
		return "Up to date"
	case "failed":
		return "Failed"
	case "stopped":
		return "Stopped"
	default:
		return phase
	}
}

